const TYPES_SCORED_AT_FACE_VALUE = 3;
const POINTS_PER_SPHINX = 1;

const distinctNonSphinxTypes = (army: Card[]): number =>
  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
    .size;

const pointsForOtherTypes = (typeCount: number): number =>
  typeCount > TYPES_SCORED_AT_FACE_VALUE ? 2 : 1;

const scoreOneSphinx = (otherTypes: number): number =>
  POINTS_PER_SPHINX + pointsForOtherTypes(otherTypes);

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  return sphinxCount * scoreOneSphinx(distinctNonSphinxTypes(army));
};
